   const result = await routeCall({ task_type: 'insight_generation', tier_class: 'text', complexity: 'apex', context_tokens: 800, constitutional_flag: true, agent_id: 'scs001-insight', payload: { prompt: prompt } });
   const content = result.content;
   const costUsd = result.cost_usd;
